type Authority<I,T>=OriginalEffectAuthority<NativeSlotProducer<I,T,<T as NativeReceive<I>>::Receiver>>;
/// 🪪️ The registered codec supplies its genuine typed input source and required receiver without a cold conversion.
pub struct NativeReceivingOriginal<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync=I>{original:ManuallyDrop<Option<OriginalInput<I,A>>>,receiver:semio_framework_value_native_storage::NativeOwnedStorage<T::Receiver>,retired_header:Option<Box<T::Receiver>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,action:semio_framework_value_native_receiver_protocol::NativeReceivingChild<OriginalReceivingPrimary>,authority:ManuallyDrop<Option<Authority<I,T>>>,closing:bool}
fn original_seed<I:Sync+'static,T:NativeReceive<I>>(_:bool)->Result<T::Receiver,ValueError>{Ok(T::receiver())}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native original receiving is not in the required funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(copy_bytes:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,..Default::default()}}
fn nested(mut d:RetirementDemand,copy:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(copy).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> NativeReceivingOriginal<I,T,A>{
 pub fn new(original:RetainedCloneSource<I,A>)->Self{Self{original:ManuallyDrop::new(Some(OriginalInput::Source(original))),receiver:semio_framework_value_native_storage::NativeOwnedStorage::empty(),retired_header:None,output:ManuallyDrop::new(None),retirement:Default::default(),action:Default::default(),authority:ManuallyDrop::new(Some(OriginalEffectAuthority::new(NativeSlotProducer::new()))),closing:false}}
 pub fn borrow_input(&self)->Result<RetainedCloneRef<'_,I>,ValueError>{if self.closing{return Err(invalid())}self.original.as_ref().ok_or_else(invalid)?.try_borrow()}
 pub fn demands(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}if let Some(d)=self.action.demand{return Ok(d)}if !self.receiver.reserved(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::reserve_demand())}if !self.receiver.initialized(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::seed_demand())}let receiver=self.receiver.get().ok_or_else(||ValueError::invariant("get target absent"))?;nested(if receiver.output_ready(){receiver.take_demand()?}else{receiver.demands(self.borrow_input()?,body,maximum_work_units)?},0)}
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{
  let done=|result:Result<RetainedCloneStep,OriginalReceivingPrimary>|->RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{RetainedWorkPoll::Complete(RetainedWorkOutcome{result,work:0})};
  if self.action.request.is_some_and(|request|request!=(body,maximum_work_units)){return done(Err(ValueError::invariant("original local receiver request changed").into()))}
  if maximum_work_units==0{return if self.action.demand.is_some(){RetainedWorkPoll::Pending{work:0}}else{done(Ok(RetainedCloneStep::Progress(Default::default())))}}
  let result:Result<RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>,OriginalReceivingPrimary>=(||{
   let d=self.demands(body,maximum_work_units)?;if !retained_clone_grant_admits(g,d){return Ok(if self.action.demand.is_some(){RetainedWorkPoll::Pending{work:0}}else{done(Ok(RetainedCloneStep::Progress(Default::default())))})}
   if self.action.demand.is_none(){control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?}
   let input=self.original.as_ref().ok_or_else(invalid)?.try_borrow()?;let authority=self.authority.as_mut().ok_or_else(invalid)?;
   if !self.receiver.reserved()||self.action.tag==3{self.action.tag=3;let units=self.action.work.unwrap_or_else(||self.receiver.reserve_work_demand());return Ok(self.action.poll(control,d,g,units,maximum_work_units,authority,|_,effect,authority,action|authority.drive(&mut NativeSlotOperation::Reserve(input,&mut self.receiver),effect,action)))}
   if !self.receiver.initialized()||self.action.tag==4{self.action.tag=4;let units=self.action.work.unwrap_or_else(||self.receiver.seed_work_demand());return Ok(self.action.poll(control,d,g,units,maximum_work_units,authority,|_,effect,authority,action|authority.drive(&mut NativeSlotOperation::Seed(input,&mut self.receiver,false,original_seed::<I,T>),effect,action)))}
   let receiver=self.receiver.get_mut().ok_or_else(||ValueError::invariant("get_mut target absent"))?;
   if receiver.output_ready()||self.action.tag==5{self.action.tag=5;let units=match self.action.work{Some(work)=>work,None=>receiver.take_work_demand()?};return Ok(self.action.poll(control,d,g,units,maximum_work_units,authority,|_,effect,authority,action|authority.drive(&mut NativeSlotOperation::Publish(input,receiver,&mut self.output),effect,action)))}
   let selection=if self.action.tag==6{NativeAdvanceSelection::Local{work:self.action.work.ok_or_else(||ValueError::invariant("original local receiver action lost its work quote"))?}}else{receiver.select_advance(input,body,maximum_work_units)?};
   match selection{
    NativeAdvanceSelection::Nested=>Ok(receiver.advance_nested(input,control,body,maximum_work_units,RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g}).map(|step|RetainedCloneStep::Progress(step.progress()))),
    NativeAdvanceSelection::Local{work}=>{if self.action.demand.is_none()&&work>maximum_work_units{return Ok(done(Ok(RetainedCloneStep::Progress(Default::default()))))}self.action.tag=6;Ok(self.action.poll_local(control,d,g,work,body,maximum_work_units,authority,|_,effect,authority,action|authority.drive(&mut NativeSlotOperation::Advance(input,receiver,body),effect,action)))}
   }
  })();
  match result{Ok(turn)=>turn,Err(error)=>done(Err(error))}
 }
 pub fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 semio_framework_value_native_receiver_protocol::native_owned_public_output!(T,invalid,output_ready);
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.get_mut(){receiver.begin_close()}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.receiver.reserved()||self.retired_header.is_some(){return crate::owned::native_receiver_backing_demands::<I,T,_>(&self.receiver,&self.retired_header,body)}if !self.retirement.is_empty(){return nested(self.retirement.next_owner_demands::<T>(false,&None,body)?,0)}if self.action.failure.is_some(){return nested(self.action.failure_demand(&self.retirement,body)?,0)}if self.output.is_some(){return nested(self.retirement.next_owner_demands::<T>(true,&None,body)?,0)}if self.authority.is_some(){return nested(self.retirement.next_owner_demands::<Authority<I,T>>(true,&None,body)?,0)}if let Some(original)=self.original.as_ref(){return if original.terminal_is_empty(){Ok(fixed(0))}else{nested(original.next_close_demand(body)?,0)}}Ok(Default::default())}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.close_work_demand(body)}}if self.receiver.reserved()||self.retired_header.is_some(){return Ok(1)}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<T>(false,&None,body)}if self.action.failure.is_some(){return self.action.failure_work(&self.retirement,body)}if self.output.is_some(){return self.retirement.next_owner_work::<T>(true,&None,body)}if self.authority.is_some(){return self.retirement.next_owner_work::<Authority<I,T>>(true,&None,body)}match self.original.as_ref(){Some(original)if !original.terminal_is_empty()=>original.next_close_work(body),Some(_)=>Ok(1),None=>Ok(0)}}
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{
  use crate::RetainedWorkPoll::Complete;let fail=|error:ValueError|->semio_framework_value_retirement::OriginalRetirementPoll{Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};
  if self.requires_original_control(){return fail(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native original receiver requires its original close loan"))}
  let g=effect.grant();if self.terminal_is_empty(){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}
  let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return fail(error)};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}
  let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};
  if self.receiver.reserved()||self.retired_header.is_some(){if let Some(receiver)=self.receiver.get_mut().filter(|receiver|!receiver.terminal_is_empty()){return receiver.close_step(&mut effect.nested(child)).map(|s|RetainedCloneStep::Progress(s.progress()))}return crate::owned::close_native_receiver_backing::<I,T,_>(&mut self.receiver,&mut self.retired_header,effect).map(|s|RetainedCloneStep::Progress(s.progress()))}
  if !self.retirement.is_empty(){return self.retirement.step_granted(&mut effect.nested(child)).map(|s|RetainedCloneStep::Progress(s.progress()))}
  if self.action.failure.is_some(){return Complete(self.action.close_failure(&mut self.retirement,&mut effect.nested(child)))}
  if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,&mut effect.nested(child));return Complete(RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}
  if self.authority.is_some(){let turn=self.retirement.begin_granted(&mut self.authority,&mut effect.nested(child));return Complete(RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}
  if let Some(original)=self.original.as_mut(){if !original.terminal_is_empty(){return original.close_step(&mut effect.nested(child)).map(|s|RetainedCloneStep::Progress(s.progress()))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return fail(ValueError::literal(ValueRefusalKind::WorkLimit,"native original receiver release exceeded its work authority")),Err(error)=>return fail(error)}self.original.take();return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(0))),work:1})}
  Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})
 }
 /// 👶️ Selects an unfinished birth before any general close effect is opened.
 pub fn requires_original_birth(&self)->bool{if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.requires_original_birth()}}if self.receiver.reserved()||self.retired_header.is_some(){return false}self.retirement.requires_original_birth()}
 /// 🧷️ Resumes the same recipient’s pending physical birth without creating another marker.
 pub fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;if grant.maximum_items==0||grant.maximum_depth==0{return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}let child=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};if let Some(receiver)=self.receiver.get_mut(){if !receiver.terminal_is_empty()&&receiver.requires_original_birth(){return receiver.close_original_birth_step(original,child)}}if !self.receiver.reserved()&&self.retired_header.is_none()&&self.retirement.requires_original_birth(){return self.retirement.step_original_birth(original,child)}Complete(RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native original receiver has no birth to settle").into()),work:0})}
 /// 🪪️ Reports whether the selected original receiver needs its own close loan.
 pub fn requires_original_control(&self)->bool{if self.action.pending(){return true}if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.requires_original_control()}}if self.receiver.reserved()||self.retired_header.is_some(){return false}self.retirement.requires_original_control()}
 /// 🧵️ Relays the exact original loan to the active receiver or retirement owner.
 pub fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;let fail=|error:ValueError|->semio_framework_value_retirement::OriginalRetirementPoll{Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};
  if self.action.pending(){return fail(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original receiver birth requires settlement"))}
  if self.requires_original_birth(){return fail(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"settle original birth before opening a close effect"))}
  let g=effect.grant();let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return fail(error)};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}
  let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};
  if let Some(receiver)=self.receiver.get_mut(){if !receiver.terminal_is_empty()&&receiver.requires_original_control(){return receiver.close_original_step(original,&mut effect.nested(child))}}
  if !self.receiver.reserved()&&self.retired_header.is_none()&&self.retirement.requires_original_control(){return self.retirement.step_original(original,&mut effect.nested(child))}
  self.close_step(effect)}
 pub fn terminal_is_empty(&self)->bool{self.receiver.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.action.terminal_is_empty()&&self.authority.is_none()&&self.original.is_none()}
}
/// 🌱️ Inline seed starts the actual receiver close only after a funded retirement turn.
#[doc(hidden)]
pub struct NativeReceivingOriginalSeed<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync>{owner:ManuallyDrop<Option<NativeReceivingOriginal<I,T,A>>>,started:bool}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetireOwned for NativeReceivingOriginal<I,T,A>{type RetirementCursor=NativeReceivingOriginalSeed<I,T,A>;fn retirement_seed(self)->Self::RetirementCursor{NativeReceivingOriginalSeed{owner:ManuallyDrop::new(Some(self)),started:false}}fn controlled_retirement_supported()->bool{true}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginalSeed<I,T,A>{
 fn requires_original_birth(&self)->bool{self.started&&self.owner.as_ref().is_some_and(NativeReceivingOriginal::requires_original_birth)}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{let Some(owner)=self.owner.as_mut()else{return RetirementStep::Complete(0)};crate::retirement::erased_cursor_turn(owner.close_original_birth_step(original,grant))}
 fn requires_original_control(&self)->bool{self.started&&self.owner.as_ref().is_some_and(NativeReceivingOriginal::requires_original_control)}
 fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let Some(owner)=self.owner.as_mut()else{return RetirementStep::Complete(0)};crate::retirement::erased_cursor_turn(owner.close_original_step(original,effect))}
 fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{match self.owner.as_ref(){None=>Ok(Default::default()),Some(owner)if self.started=>owner.close_demands(body),Some(_)=>Ok(fixed(0))}}
 fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{match self.owner.as_ref(){None=>Ok(0),Some(owner)if self.started=>owner.close_work_demand(body),Some(_)=>Ok(1)}}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let g=effect.grant();if self.terminal_is_empty(){return RetirementStep::Complete(0)}if !self.started{if effect.maximum_work_units()==0||!retained_clone_grant_admits(g,fixed(0)){return RetirementStep::BudgetExhausted}self.owner.as_mut().expect("retained original receiver").begin_close();self.started=true;return RetirementStep::Progress(receipt(0),1)}crate::retirement::erased_cursor_turn(self.owner.as_mut().expect("retained original receiver").close_step(effect))}
 fn terminal_is_empty(&self)->bool{self.started&&self.owner.as_ref().is_none_or(NativeReceivingOriginal::terminal_is_empty)}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginalSeed<I,T,A>{fn drop(&mut self){if !std::thread::panicking(){assert!(self.terminal_is_empty(),"original receiver seed requires funded closure");unsafe{ManuallyDrop::drop(&mut self.owner)}}}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginal<I,T,A>{fn requires_original_birth(&self)->bool{Self::requires_original_birth(self)}fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{crate::retirement::erased_cursor_turn(Self::close_original_birth_step(self,original,grant))}fn requires_original_control(&self)->bool{Self::requires_original_control(self)}fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{crate::retirement::erased_cursor_turn(Self::close_original_step(self,original,effect))}fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{self.close_work_demand(body)}fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let g=effect.grant();crate::retirement::erased_cursor_turn(Self::close_step(self,&mut effect.nested(g)))}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginal<I,T,A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native receiving keeps original custody until funded closure");}}
